        # If the start and goal are the same, there is a direct path
        return [start]

    visited = set()  # To keep track of already visited nodes
    queue = [(start, [start])]  # A queue of tuples (node, path)

    while queue:
        (current_node, path) = queue.pop(0)
        visited.add(current_node)

        for neighbor in graph[current_node]:
            if neighbor not in visited:
                if neighbor == goal:
                    # If the goal is reached, return the full path
                    return path + [neighbor]
                else:
                    # Otherwise, add the neighbor to the queue with updated path
